package com.example.smartpantrymanager;
import android.view.*;import android.widget.TextView;import androidx.recyclerview.widget.RecyclerView;import java.util.List;
public class RecipeAdapter extends RecyclerView.Adapter<RecipeAdapter.Holder>{public interface Listener{void click(Recipe r);}private final List<Recipe>d;private final Listener l;public RecipeAdapter(List<Recipe>x,Listener y){d=x;l=y;}public Holder onCreateViewHolder(ViewGroup p,int v){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_recipe,p,false));}public void onBindViewHolder(Holder h,int i){Recipe r=d.get(i);h.t.setText(r.getName());h.itemView.setOnClickListener(v->l.click(r));}public int getItemCount(){return d.size();}static class Holder extends RecyclerView.ViewHolder{TextView t;Holder(View v){super(v);t=v.findViewById(R.id.recipe_name);}}}
